mapper.select:
SELECT
    f.id, f.object_key, f.original_name, f.extension, f.size,
    f.biz, f.biz_id, f.is_public, f.dept_id, f.create_by, f.create_time
FROM sys_file f

    f.deleted = 0

        AND f.original_name LIKE CONCAT('%', #{q.keywords}, '%')


        AND f.biz = #{q.biz}


        AND f.biz_id = #{q.bizId}


        AND f.is_public = #{q.isPublic}


ORDER BY f.create_time DESC
